37: const REGEX_CHECKED_LISTITEM = /^\[x]\s+/;
38: const REGEX_UNCHECKED_LISTITEM = /^\[ ]\s+/;
39: 
40: class MarkdownRenderer {
41:     private renderer: MarkedRenderer;
42: 
43:     constructor(public markdown_exts: string[]) {
44:         console.log(this.markdown_exts);
45:         this.renderer = new marked.Renderer();
46:         const self = this;
47: 
48:         this.renderer.listitem = function(text: string) {
49:             let matched = text.match(REGEX_CHECKED_LISTITEM);
50:             if (matched && matched[0]) {
51:                 return '<li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" checked="checked" disabled="disabled">'
52:                     + text.slice(matched[0].length) + '</li>\n';
53:             }
54: 
55:             matched = text.match(REGEX_UNCHECKED_LISTITEM);
56:             if (matched && matched[0]) {
57:                 return '<li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" disabled="disabled">'
58:                     + text.slice(matched[0].length) + '</li>\n';
59:             }
60: 
61:             return marked.Renderer.prototype.listitem.call(this, text);
62:         };
63: 
64:         this.renderer.text = function(text: string) {
65:             return emoji_replacer.replaceWithImages(text);
66:         };
67: 
68:         this.renderer.link = function(href: string, title: string, text: string) {
69:             const link = marked.Renderer.prototype.link;
70:             if (!href) {
71:                 return link.call(this, href, title, text);
72:             }
73: 
74:             if (this.options.sanitize) {
75:                 try {
76:                     const prot = decodeURIComponent(unescape(href))
77:                         .replace(/[^\w:]/g, '')
78:                         .toLowerCase();
79:                     if (prot.startsWith('javascript:') || prot.startsWith('vbscript:')) {
80:                         return '';
81:                     }
82:                 } catch (e) {
83:                     return '';
84:                 }
85:             }
86: 
87:             let onclick = 'cancelClick(event)';
88:             const ext_idx = href.lastIndexOf('.');
89: 
90:             if (href.startsWith('http://') || href.startsWith('https://')) {
91:                 onclick = 'openLinkWithExternalBrowser(event)';
92:             } else if (ext_idx !== -1) {
93:                 const ext = href.slice(ext_idx + 1);
94:                 if (self.markdown_exts.indexOf(ext) !== -1) {
95:                     onclick = 'openMarkdownLink(event)';
96:                 }
97:             } else if (href.indexOf('#') !== -1) {
98:                 onclick = 'openHashLink(event)';
99:             }
100: 
101:             if (title !== null) {
102:                 return `<a href="${href}" onclick="${onclick}" title=${title}>${text}</a>`;
103:             } else {
104:                 return `<a href="${href}" onclick="${onclick}">${text}</a>`;
105:             }
106:         };
107:     }
108: 
109:     render(markdown: string): string {
110:         return marked(markdown, {renderer: this.renderer});
111:     }
112: }
